insert into job_posts(id, source, org_name, title, url, job_group, employ_type, headcount, apply_from, apply_to, apply_to_time, sido, sgg, work_place, "기관번호", "연결상태", "뽑은값", detail, hold, hidden, first_seen) values ('306315', 'AL2', '부산대학교병원', '2026년도 10월 블라인드 공개채용 계약직 (보건직, 행정직, 원무직) 모집 공고', 'https://job.alio.go.kr/recruitview.do?idx=306315', '공통', '계약직', 2, '2026-10-26'::date, '2026-11-09'::date, '10:00:00'::time, NULL, NULL, '경남', 'HIRA:JDQ4MTAxMiM1MSMkMSMkMCMkODkkMzgxMzUxIzExIyQxIyQzIyQ3OSQyNjEyMjIjNDEjJDEjJDgjJDgz', '자동', '{"근무지": ") 한시적/ 휴직 대체 보건직 임상병리사 (진단검사의학과) 2 ⦁임상병리사 면허증 소지자 -업무내용: 임상병", "읽은법": "kordoc", "예상연봉": "내규에 따름", "지원자격": "⦁물리치료사 면허증 소지자로서 아래 관련 교육 중 1개 이상 이수자 &lt;관련 교육 과정&gt; -대한재활의학회 중추신경계 발달 재활치료 연수교육 -한국보바스협회 보바스 베이직 코스 -대한고유수용성신경근촉진법학회 PNF level 1,2또는Advance교육", "직군별인원": {"물리치료사": 3, "작업치료사": 1}, "공고문_접수마감": "2026-11-09", "공고문_접수시각": "10:00"}'::jsonb, E'{"연봉": "내규에 따름", "기관홈": "https://pnuyh.recruiter.co.kr/career/jobs/132239", "결격사유": "1. 피성년후견인, 피한정후견인 또는 피특정후견인\\n2. 파산선고를 받은 자로서 복권되지 아니한 자\\n3. 금고이상의 형을 받고 그 집행이 종료되거나 또는 집행을 받지 아니하기로 확정된 후 5년을 경과하지 아니한 자\\n4. 금고이상의 형을 받고 그 집행유예의 기간이 만료된 날로 부터 2년을 경과하지 아니한 자\\n5. 금고이상의 형의 선고유예를 받고 그 선고유예기간 중에 있는 자\\n6. 법원의 판결 또는 다른 법률에 따라 자격이 상실되거나 정지된 자\\n6의2. 공무원으로 재직기간 중 직무와 관련하여 「형법」 제355조 및 제356조에 규정된 죄를 범한 자로서 300만원 이상의 벌금형을 선고받고 그 형이 확정된 후 2년이 지나지 아니한 자\\n6의3. 「성폭력범죄의 처벌 등에 관한 특례법」 제2조에 규정된 죄를 범한 사람으로서 100만원 이상의 벌금형을 선고받고 그 형이 확정된 후 3년이 지나지 아니한 사람\\n6의4. 미성년자에 대한 다음 각 목의 어느 하나에 해당하는 죄를 저질러 파면ㆍ해임되거나 형 또는 치료감호를 선고받아 그 형 또는 치료감호가 확정된 사람(집행유예를 선고받은 후 그 집행유예기간이 경과한 사람을 포함한다)\\n가. 「성폭력범죄의 처벌 등에 관한 특례법」 제2조에 따른 성폭력범죄\\n나. 「아동ㆍ청소년의 성보호에 관한 법률」 제2조제2호에 따른 아동ㆍ청소년대상 성범죄\\n7. 병역의무자로서 병역을 기피한 자\\n8. 징계로 파면처분을 받은 때부터 5", "우대사항": "취업지원대상자(보훈대상자), 장애인: 전형단계별 5~10%가점부여", "전형방법": "1. 전형절차 : 1차 서류전형 -> 2차 면접전형 -> 최종합격자발표\\n2. 전형단계별 선발예정 배수 및 평가방법\\n- 1차(서류전형) : 선발예정인원의 최대 5배수 범위 내, 입사지원서(적/부)\\n- 2차(면접전형) : 선발예정인원의 1배수, 임원 면접점수\\n- 최종합격자 발표 : 제출서류 적격 확인", "지원자격": "[보건직_임상병리사(진단검사의학과)]임상병리사 면허증 소지자, [보건직_방사선사(영상의학과)]방사선사 면허증 소지자,[보건직_보건의료정보관리사]보건의료정보관리사 면허증 소지자,[보건직_임상병리사(병리과]임상병리사 면허증 소지자,[보건직_물리치료사(재활의학과)]?물리치료사 면허증 소지자로서 아래 관련 교육 중 1개 이상 이수자<관련 교육 과정>-대한재활의학회 중추신경계   발달 재활치료 연수교육-한국보바스협회 보바스 베이직   코스-대한고유수용성신경근촉진법학회   PNF level 1,2또는Advance교육,[보건직_작업치료사(재활의학과)]작업치료사 면허증 소지자,[행정직_일반행정]워드프로세서 또는 컴퓨터활용능력 자격증 소지자, [원무직_업무지원] 해당사항 없음", "직군인원": {"물리치료사": 1, "작업치료사": 1}, "공고전체인원": 17, "직군인원근거": "보건직_물리치료사 → 물리치료사 1 / 보건직_작업치료사 → 작업치료사 1", "알리오기관코드": "C0071", "알리오표준기관코드": "B550554"}'::jsonb, false, false, '2026-10-26'::timestamptz);
insert into job_posts(id, source, org_name, title, url, job_group, employ_type, headcount, apply_from, apply_to, apply_to_time, sido, sgg, work_place, "기관번호", "연결상태", "뽑은값", detail, hold, hidden, first_seen) values ('306314', 'AL2', '부산대학교병원', '2026년도 10월 블라인드 공개채용 국비계약직(작업치료사) 모집 공고', 'https://job.alio.go.kr/recruitview.do?idx=306314', '작업치료사', '계약직', 1, '2026-10-26'::date, '2026-11-09'::date, '10:00:00'::time, NULL, NULL, '경남', 'HIRA:JDQ4MTAxMiM1MSMkMSMkMCMkODkkMzgxMzUxIzExIyQxIyQzIyQ3OSQyNjEyMjIjNDEjJDEjJDgjJDgz', '자동', '{"읽은법": "kordoc", "예상연봉": "내규에 따름", "지원자격": "⦁ 작업치료사 면허증 소지자로서 3년 이상 업무(작업치료) 경력자", "직군별인원": {"작업치료사": 1}, "공고문_접수마감": "2026-11-09", "공고문_접수시각": "10:00"}'::jsonb, E'{"연봉": "내규에 따름", "기관홈": "https://pnuyh.recruiter.co.kr/career/jobs/132238", "결격사유": "1. 피성년후견인, 피한정후견인 또는 피특정후견인\\n2. 파산선고를 받은 자로서 복권되지 아니한 자\\n3. 금고이상의 형을 받고 그 집행이 종료되거나 또는 집행을 받지 아니하기로 확정된 후 5년을 경과하지 아니한 자\\n4. 금고이상의 형을 받고 그 집행유예의 기간이 만료된 날로 부터 2년을 경과하지 아니한 자\\n5. 금고이상의 형의 선고유예를 받고 그 선고유예기간 중에 있는 자\\n6. 법원의 판결 또는 다른 법률에 따라 자격이 상실되거나 정지된 자\\n6의2. 공무원으로 재직기간 중 직무와 관련하여 「형법」 제355조 및 제356조에 규정된 죄를 범한 자로서 300만원 이상의 벌금형을 선고받고 그 형이 확정된 후 2년이 지나지 아니한 자\\n6의3. 「성폭력범죄의 처벌 등에 관한 특례법」 제2조에 규정된 죄를 범한 사람으로서 100만원 이상의 벌금형을 선고받고 그 형이 확정된 후 3년이 지나지 아니한 사람\\n6의4. 미성년자에 대한 다음 각 목의 어느 하나에 해당하는 죄를 저질러 파면ㆍ해임되거나 형 또는 치료감호를 선고받아 그 형 또는 치료감호가 확정된 사람(집행유예를 선고받은 후 그 집행유예기간이 경과한 사람을 포함한다)\\n가. 「성폭력범죄의 처벌 등에 관한 특례법」 제2조에 따른 성폭력범죄\\n나. 「아동ㆍ청소년의 성보호에 관한 법률」 제2조제2호에 따른 아동ㆍ청소년대상 성범죄\\n7. 병역의무자로서 병역을 기피한 자\\n8. 징계로 파면처분을 받은 때부터 5", "우대사항": "취업지원대상자(보훈대상자), 장애인: 전형단계별 5~10%가점부여", "전형방법": "1. 전형절차 : 1차 서류전형 -> 2차 면접전형 -> 최종합격자발표\\n2. 전형단계별 선발예정 배수 및 평가방법\\n- 1차(서류전형) : 선발예정인원의 최대 5배수 범위 내, 입사지원서(적/부)\\n- 2차(면접전형) : 선발예정인원의 1배수, 임원 면접점수\\n- 최종합격자 발표 : 제출서류 적격 확인", "지원자격": "[작업치료사(지역장애인보건의료센터)]작업치료사 면허증 소지자로서 3년 이상 업무(작업치료) 경력자", "공고전체인원": 1, "알리오기관코드": "C0071", "알리오표준기관코드": "B550554"}'::jsonb, false, false, '2026-10-26'::timestamptz);
insert into job_posts(id, source, org_name, title, url, job_group, employ_type, headcount, apply_from, apply_to, apply_to_time, sido, sgg, work_place, "기관번호", "연결상태", "뽑은값", detail, hold, hidden, first_seen) values ('306248', 'AL2', '한국보훈복지의료공단', '[대전보훈병원] 정규직(약무직(약사), 업무지원직(완화의료)) 및 계약직(일반기능직(시설(영선)), 청년인턴(체험형)) 채용공고', 'https://job.alio.go.kr/recruitview.do?idx=306248', '물리치료사', '', 4, '2026-10-22'::date, '2026-11-05'::date, '11:59:00'::time, NULL, NULL, '대전', 'HIRA:JDQ4MTYyMiM2MSMkMSMkMiMkODkkMzgxMzUxIzExIyQxIyQzIyQ5OSQyNjE4MzIjNzEjJDEjJDgjJDgz', '자동', '{"읽은법": "kordoc", "예상연봉": "내규에 따름", "지원자격": "(필수) 물리치료사 면허증 소지자", "직군별인원": {"물리치료사": 4}, "공고문_접수마감": "2026-11-05", "공고문_접수시각": "11:59"}'::jsonb, E'{"연봉": "내규에 따름", "기관홈": "https://www.bohun.or.kr/daejeon/na/ntt/selectNttInfo.do?mi=33414&bbsId=1158&bbsSysId=daejeon&nttSn=190634", "결격사유": "① 다음 각 호의 어느 하나에 해당하는 사람은 직원에 임용될 수 없다. \\r\\n  1. 피성년후견인\\r\\n  2. 파산선고를 받은 자로서 복권되지 아니한 사람 \\r\\n  3. 금고 이상의 실형을 선고받고 그 집행이 끝나거나(집행이 끝난 것으로 보는 경우를 포함한다) 집행이 면제된 날부터 5년이 지나지 아니한 사람\\r\\n  4. 금고 이상의 형의 집행유예를 선고받고 그 유예기간이 끝난 날부터 2년이 지나지 아니한 사람\\r\\n  5. 금고 이상의 형의 선고유예를 받은 경우에 그 선고유예 기간 중에 있는 사람 \\r\\n  6. 법원의 판결 또는 다른 법률에 의하여 자격이 상실 또는 정지된 사람        \\r\\n  6의2. 직무와 관련하여「형법」제355조 및 제356조에 규정된 죄를 범한 자로서 300만원 이상의 벌금형을 선고받고 그 형이 확정된 후 2년이 지나지 아니한 자 \\r\\n  6의3. 다음 각 목의 어느 하나에 해당하는 죄를 범한 사람으로서 100만원 이상의 벌금형을 선고받고 그 형이 확정된 후 3년이 지나지 아니한 사람 <신설 16.7.28> <개정 19.7.2, 23.9.21>\\r\\n   가. 「성폭력범죄의 처벌 등에 관한 특례법」 제2조에 따른 성폭력범죄 <신설 23.9.21> \\r\\n   나. 「정보통신망 이용촉진 및 정보보호 등에 관한 법률」 제74조제1항제2호 및 제3호에 규정된 죄 <신설 23.9.21>\\r\\n   다. 「스토킹범죄의 처벌 등에 관한 법률」", "우대사항": "- 취업지원대상자: 「국가유공자 예우 및 지원에 관한 법률」 제29조, 면접시험 만점의 5∼10% \\r\\n- 장애인: 「장애인고용촉진 및 직업재활법」에 따른 장애인, 면접시험 만점의 10%", "전형방법": "- 공고 및 접수: ''26. 10. 22.(목) ∼ 11. 5.(목), 채용사이트 접수\\r\\n- 서류합격발표: ''26. 11. 6.(금), 홈페이지 발표 및 개별 통보\\r\\n- 면접시험: ''26. 11. 10.(화), 장소 및 시간 별도 공지\\r\\n- 채용검증위원회: ''26. 11. 12.(목), 자체 채용검증위원회 실시\\r\\n- 합격자 발표: ''26. 11. 16.(월), 대전보훈병원 홈페이지 게시 및 개별 안내\\r\\n- 서류등록: ''26. 11. 17.(화) ~ 11. 19.(목), 채용 신체검사 포함\\r\\n- 임용(예정일): ''26. 12. 1.(화) \\r\\n\\r\\n※ 평가기준\\r\\n- 서류전형: (평가기준) 적격여부 확인, (선발인원) 적격자 전원선발\\r\\n- 면접시험(100%): (평가기준) 직업기초 및 직무수행능력 등, (선발인원) 채용계획 인원 2명 및 예비합격자 운영 시 채용인원의 2배수, (동점자 처리기준) ① 취업지원대상자 - ② 면접 고득점자 - ③ 면접평가항목 中  직무수행능력 고득점자 - ④ 면접평가항목 中 직업기초능력 항목 순 고득점자\\r\\n※ 자세한 사항은 공고문 참고", "지원자격": "1) 공통\\r\\n- 공단 인사규정 *제18조(결격사유 및 임용취소)에 해당하지 않는 자\\r\\n- 공단 인사규정 제44조(정년)에 따른 정년(60세)를 초과하지 않는 자\\r\\n ※ 단, 업무지원직(완화의료)의 경우, 공단 업무지원직 인사관리 시행세칙 제13조(정년)에 따른 정년(65세)를 초과하지 않는 자\\r\\n2) 정규직 - 약무직(약사)\\r\\n- 약사 면허증 소지자\\r\\n3) 정규직(무기계약직) - 업무지원직(완화의료)\\r\\n- (필수) 한국호스피스·완화의료학회 주관 호스피스보조활동인력 교육 40시간(이론 20시간, 실습 20시간) 이수자\\r\\n- (우대) 요양보호사 자격증 소지자\\r\\n4) 계약직 - 일반기능직(영선)\\r\\n - (우대) 건축도장, 건축목공, 도배, 미장, 방수, 타일, 실내건축 기능사 이상 자격증 중 1개 이상 소지자\\r\\n5) 계약직 - 청년인턴(체험형)\\r\\n - (필수) 청년고용촉진 특별법령에 따른 만 15세 이상 만 34세 이하인 청년\\r\\n - (필수) 물리치료사 면허증 소지자", "공고전체인원": 8, "알리오기관코드": "C0203", "알리오표준기관코드": "B551202"}'::jsonb, false, false, '2026-10-22'::timestamptz);
insert into job_posts(id, source, org_name, title, url, job_group, employ_type, headcount, apply_from, apply_to, apply_to_time, sido, sgg, work_place, "기관번호", "연결상태", "뽑은값", detail, hold, hidden, first_seen) values ('306236', 'AL2', '대한적십자사', '(거창적십자병원) 초단시간 근로자 보건직 물리치료사 1차 채용', 'https://job.alio.go.kr/recruitview.do?idx=306236', '물리치료사', '계약직', 1, '2026-10-23'::date, '2026-11-08'::date, '18:00:00'::time, NULL, NULL, '경남', 'NAME:대한적십자사', '없음', '{"근무지": "거창적십자병원 의료부 정형외과 물리치료실", "읽은법": "kordoc", "예상연봉": "내규에 따름", "지원자격": "물리치료사 면허증 소지자", "직군별인원": {"물리치료사": 1}, "공고문_접수마감": "2026-11-08", "공고문_접수시각": "18:00"}'::jsonb, E'{"연봉": "내규에 따름", "기관홈": "https://www.redcross.or.kr/redrecruit/", "결격사유": "1. 피성년후견인과 피한정후견인\\r\\n2. 파산자로서 복권되지 아니한 자\\r\\n3. 금고 이상의 실형을 선고받고 그 집행이 끝나거나(집행이 끝난 것으로 보는 경우를\\r\\n포함한다) 집행이 면제된 날부터 5년이 지나지 아니한 자\\r\\n4. 금고이상의 형을 받고 그 집행유예의 기간이 완료된 날로부터 2년을 경과하지 아니한 자\\r\\n5. 금고이상의 형의 선고유예를 받은 경우에 그 선고유예기간중에 있는 자\\r\\n6. 법원의 판결 또는 다른 법률에 의하여 자격이 상실 또는 정지된 자\\r\\n7. 징계에 의하여 파면의 처분을 받은 때로부터 5년을 경과하지 아니한 자\\r\\n8. 징계에 의하여 해임의 처분을 받은 때로부터 3년을 경과하지 아니한 자\\r\\n9. 부패방지 및 국민권익위원회의 설치와 운영에 관한 법률 제82조에 따른 비위\\r\\n면직자 등의 취업제한 적용을 받는 자\\r\\n10. 공공기관에서 채용비위로 면직 또는 채용취소된 때부터 5년이 지나지 아니한 자\\r\\n11. 다음 각 목의 어느 하나에 해당하는 죄를 범한 사람으로서 100만원 이상의 벌금형을\\r\\n선고받고 그 형이 확정된 후 3년이 지나지 아니한 자\\r\\n가. 「성폭력범죄의 처벌 등에 관한 특례법」 제2조에 따른 성폭력범죄\\r\\n나. 「정보통신망 이용촉진 및 정보보호 등에 관한 법률」 제74조제1항제2호 및 제3호에 규정된 죄\\r\\n다. 「스토킹범죄의 처벌 등에 관한 법률」 제2조제2호에 따른 스토킹범죄\\r\\n12. 미성년자에 대한 다음 각 목", "우대사항": "<우대사항>\\r\\n○ 국가유공자 등 예우 및 지원에 관한 법률 제29조 및 독립유공자 예우에 관한 법률 제16조, 5·18 민주유공자 예우 및 단체설립에 관한 법률 제20조, 특수임무유공자 예우 및 단체설립에 관한 법률 제19조, 보훈보상대상자 지원에 관한 법률 제33조, 고엽제후유의증 등 환자지원 및 단체설립에 관한 법률 제7조의 규정에 의한 취업보호 및 취업지원대상자\\r\\n※ 취업지원대상자 증명서 제출 시에만 인정\\r\\n○ 장애인고용촉진 및 직업 재활법 제2조1호 규정에 의한 장애인\\r\\n○ 북한이탈주민의 보호 및 정착지원에 관한 법률에 따른 북한이탈주민\\r\\n\\r\\n<자기개발요건>\\r\\n○ 성적 (최대 50점)\\r\\n* 채용분야 업무 관련 전공의 최소학력 성적만 인정\\r\\n\\r\\n○ 외국어 (최대 5점)\\r\\n- 토익 600점(TEPS(NEW TEPS 포함) 점수는 텝스관리위원회에서 최근 발표한 환산표에 의한 토익 600점에 해당하는 점수 적용(TOEFL은 제외)), 일본어 JPT 600점 이상 또는 중국어 신HSK 4급 이상 보유자\\r\\n* 채용예정일 기준 유효기간(2년) 내 점수에 한함(통합채용포털을 통해 사전 등록한 것이 인정되는 어학성적의 경우에는 연장된 유효기간이 접수 마감일 기준 유효한 경우 인정)\\r\\n\\r\\n○ 업무관련자격증 (최대 10점)\\r\\n- 컴퓨터활용능력 1급, 정보처리기사, 사무자동화산업기사, 정보처리산업기사, 워드프로세서(‘12년 이전은 워드 1급), 컴", "전형방법": "1. 접수기간 : 2026. 10. 23.(금)~2026. 11. 8.(일) 18:00\\r\\n2. 서류합격자발표 : 2026. 11. 10.(화), 16:00\\r\\n3. 면접전형 : 2026. 11. 11.(수), 15:00\\r\\n4. 최종합격자발표 : 2026. 11. 13.(금), 11:00\\r\\n5. 채용 예정일자 : 2026. 12. 1.(화)\\r\\n※ 채용 일자는 병원 사정에 의해 변동될 수 있음\\r\\n※ 세부사항은 첨부파일의 공고문 참고\\r\\n\\r\\n○ 1차 서류전형 : 모집인원의 7배수\\r\\n○ 2차 면접전형 : 서류전형 합격자", "지원자격": "○ 물리치료사 면허증 소지자", "공고전체인원": 1, "알리오기관코드": "C0059", "알리오표준기관코드": "B460004"}'::jsonb, false, false, '2026-10-23'::timestamptz);
